//! Oracle and pinned tests for the typed scene paint kernel (L07-A / F16).
//!
//! `fixtures/object-scene-style-paint/oracle.txt` was generated by
//! `tools/gen_oracle.js` from baseline fbe4b8a3: `cssColorToRgba`
//! (engine-bridge.js) and `gradGeomOk` (gradient-bridge.js) run verbatim in a Node
//! `vm`; the K and O rows transcribe engine.rs `gradient_brush` arithmetic in JS
//! doubles. Rows (space separated, `#` lines are provenance):
//! `C css opacity out`, `V from to stops ok`, `K kind coords L|R radius32`,
//! `O offset64 offset32`. Hex tokens are UTF-8 (`css`, `kind`) or f64/f32 bits.
//! `pinned_mismatches` holds hand-written literal cases for the five baseline
//! constants so the controls can show that mutating each one is noticed.

use super::{
    gradient_geometry_ok, CssColor, GradientGeometry, GradientInput, GradientOutcome,
    GradientRejection, PaintOrder, PaintRules, ScenePaintError, SceneSolid, StopInput,
};
use crate::object_document::SolidFill;

pub(crate) const ORACLE: &str = include_str!("fixtures/object-scene-style-paint/oracle.txt");

fn unhex(h: &str) -> Vec<u8> {
    (0..h.len() / 2)
        .map(|i| u8::from_str_radix(&h[2 * i..2 * i + 2], 16).expect("hex byte"))
        .collect()
}

fn text(tok: &str) -> Option<String> {
    match tok {
        "~" => None,
        "=" => Some(String::new()),
        h => Some(String::from_utf8(unhex(h)).expect("utf8")),
    }
}

fn f64_of(tok: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(tok, 16).expect("f64 bits"))
}

fn len_of(tok: &str) -> Option<usize> {
    (tok != "~").then(|| tok.parse().expect("length"))
}

fn expected_css(tok: &str) -> Option<CssColor> {
    if tok == "N" {
        return None;
    }
    let parts: Vec<&str> = tok.split(',').collect();
    assert_eq!(parts.len(), 4, "{tok}");
    if parts.iter().any(|p| *p == "NaN" || p.starts_with('-')) {
        return Some(CssColor::Unrepresentable);
    }
    let v: Vec<u8> = parts.iter().map(|p| p.parse().expect("u8")).collect();
    Some(CssColor::Rgba([v[0], v[1], v[2], v[3]]))
}

fn check_css(rules: &PaintRules, t: &[&str]) -> Option<String> {
    let css = text(t[1]);
    let opacity = (t[2] != "U").then(|| f64_of(t[2]));
    let got = rules.css_color_to_rgba(css.as_deref(), opacity);
    let want = expected_css(t[3]);
    (got != want).then(|| format!("got {got:?} want {want:?}"))
}

fn check_valid(rules: &PaintRules, t: &[&str]) -> Option<String> {
    let zeros = |tok: &str| len_of(tok).map(|n| vec![0.0f64; n]);
    let (from, to) = (zeros(t[1]), zeros(t[2]));
    let stops = len_of(t[3]).map(|n| {
        vec![
            StopInput {
                offset: 0.0,
                color: None
            };
            n
        ]
    });
    let input = GradientInput {
        kind: "linear",
        from: from.as_deref(),
        to: to.as_deref(),
        stops: stops.as_deref(),
    };
    let ok = gradient_geometry_ok(&input);
    if ok != (t[4] == "1") {
        return Some(format!("gradient_geometry_ok {ok}"));
    }
    let outcome = rules
        .prepare_gradient(&input, None)
        .expect("zeros are finite");
    let got = match &outcome {
        GradientOutcome::Rejected(why) => Some(*why),
        GradientOutcome::Ready(_) => None,
    };
    let want = if !ok {
        Some(GradientRejection::MissingGeometry)
    } else if len_of(t[3]).unwrap_or(0) < 2 {
        Some(GradientRejection::TooFewStops)
    } else {
        None
    };
    (got != want).then(|| format!("rejection {got:?} want {want:?}"))
}

fn check_kind(rules: &PaintRules, t: &[&str]) -> Option<String> {
    let kind = text(t[1]).expect("kind is never absent");
    let c: Vec<f64> = t[2].split(',').map(f64_of).collect();
    let (from, to) = ([c[0], c[1]], [c[2], c[3]]);
    let stops = [
        StopInput {
            offset: 0.0,
            color: Some("#000"),
        },
        StopInput {
            offset: 1.0,
            color: Some("#fff"),
        },
    ];
    let input = GradientInput {
        kind: &kind,
        from: Some(&from),
        to: Some(&to),
        stops: Some(&stops),
    };
    let GradientOutcome::Ready(grad) = rules.prepare_gradient(&input, None).expect("finite") else {
        return Some("rejected".to_string());
    };
    match (t[3], grad.geometry) {
        ("L", GradientGeometry::Linear { from: f, to: e }) if f == from && e == to => None,
        ("R", GradientGeometry::Radial { center, radius }) => {
            let want = u32::from_str_radix(t[4], 16).expect("f32 bits");
            (center != from || radius.to_bits() != want)
                .then(|| format!("radius {:08x} want {want:08x}", radius.to_bits()))
        }
        (out, geometry) => Some(format!("{out} but {geometry:?}")),
    }
}

fn check_offset(rules: &PaintRules, t: &[&str]) -> Option<String> {
    let stops = [
        StopInput {
            offset: f64_of(t[1]),
            color: None,
        },
        StopInput {
            offset: 1.0,
            color: None,
        },
    ];
    let (from, to) = ([0.0, 0.0], [1.0, 1.0]);
    let input = GradientInput {
        kind: "linear",
        from: Some(&from),
        to: Some(&to),
        stops: Some(&stops),
    };
    let GradientOutcome::Ready(grad) = rules.prepare_gradient(&input, None).expect("finite") else {
        return Some("rejected".to_string());
    };
    let want = u32::from_str_radix(t[2], 16).expect("f32 bits");
    let got = grad.stops[0].offset.to_bits();
    (got != want).then(|| format!("offset bits {got:08x} want {want:08x}"))
}

/// Every mismatching row of one oracle section under `rules`.
pub(crate) fn oracle_mismatches(oracle: &str, rules: &PaintRules, section: &str) -> Vec<String> {
    let mut out = Vec::new();
    for (index, line) in oracle.lines().enumerate() {
        let t: Vec<&str> = line.split(' ').collect();
        if line.starts_with('#') || t[0] != section {
            continue;
        }
        let bad = match section {
            "C" => check_css(rules, &t),
            "V" => check_valid(rules, &t),
            "K" => check_kind(rules, &t),
            "O" => check_offset(rules, &t),
            other => panic!("unknown oracle section {other}"),
        };
        if let Some(why) = bad {
            out.push(format!("{section} row {} ({line}): {why}", index + 1));
        }
    }
    out
}

fn is_ready(rules: &PaintRules, input: &GradientInput<'_>) -> bool {
    matches!(
        rules.prepare_gradient(input, None),
        Ok(GradientOutcome::Ready(_))
    )
}

/// Literal cases for the five baseline constants; each line is tagged by constant.
pub(crate) fn pinned_mismatches(rules: &PaintRules) -> Vec<String> {
    let mut out = Vec::new();
    let (from, to) = ([0.0, 0.0], [10.0, 0.0]);
    let one = [StopInput {
        offset: 0.0,
        color: Some("#ff0000"),
    }];
    let two = [
        one[0],
        StopInput {
            offset: 1.0,
            color: Some("#0000ff"),
        },
    ];
    let g1 = GradientInput {
        kind: "linear",
        from: Some(&from),
        to: Some(&to),
        stops: Some(&one),
    };
    let g2 = GradientInput {
        kind: "linear",
        from: Some(&from),
        to: Some(&to),
        stops: Some(&two),
    };
    if rules.prepare_gradient(&g1, None)
        != Ok(GradientOutcome::Rejected(GradientRejection::TooFewStops))
    {
        out.push("min_stops: one stop must be TooFewStops".to_string());
    }
    if !is_ready(rules, &g2) {
        out.push("min_stops: two stops must be a ready gradient".to_string());
    }
    for (kind, radial) in [
        ("radial", true),
        ("Radial", false),
        ("", false),
        ("radial2", false),
    ] {
        let g = GradientInput { kind, ..g2 };
        let is_radial = matches!(
            rules.prepare_gradient(&g, None),
            Ok(GradientOutcome::Ready(ref r)) if matches!(r.geometry, GradientGeometry::Radial { .. })
        );
        if is_radial != radial {
            out.push(format!(
                "radial_name: kind {kind:?} radial must be {radial}"
            ));
        }
    }
    let zero = GradientInput {
        kind: "radial",
        to: Some(&from),
        ..g2
    };
    let bits = |g: &GradientInput<'_>| match rules.prepare_gradient(g, None) {
        Ok(GradientOutcome::Ready(r)) => match r.geometry {
            GradientGeometry::Radial { radius, .. } => Some(radius.to_bits()),
            _ => None,
        },
        _ => None,
    };
    if bits(&zero) != Some(0x3c23_d70a) {
        out.push("radius_floor: zero-length radius must be 0.01f32".to_string());
    }
    let (p0, p1) = ([0.0, 0.0], [3.0, 4.0]);
    let five = GradientInput {
        kind: "radial",
        from: Some(&p0),
        to: Some(&p1),
        ..g2
    };
    if bits(&five) != Some(5.0f32.to_bits()) {
        out.push("radius_floor: 3-4-5 radius must stay 5".to_string());
    }
    for (opacity, alpha) in [
        (Some(2.0), 255u8),
        (Some(1.0), 255),
        (Some(0.4), 102),
        (Some(-1.0), 0),
    ] {
        let want = Some(CssColor::Rgba([255, 0, 0, alpha]));
        if rules.css_color_to_rgba(Some("#ff0000"), opacity) != want {
            out.push(format!(
                "alpha_ceiling: opacity {opacity:?} must give alpha {alpha}"
            ));
        }
    }
    for (name, order) in [
        (Some("strokeFirst"), PaintOrder::StrokeFirst),
        (Some("strokefirst"), PaintOrder::FillFirst),
        (Some("fillFirst"), PaintOrder::FillFirst),
        (Some(""), PaintOrder::FillFirst),
        (None, PaintOrder::FillFirst),
    ] {
        if rules.paint_order(name) != order {
            out.push(format!("stroke_first_name: {name:?} must be {order:?}"));
        }
    }
    out
}

#[test]
fn oracle_row_counts_are_pinned() {
    let rows = |section: &str| {
        ORACLE
            .lines()
            .filter(|l| l.starts_with(&format!("{section} ")))
            .count()
    };
    assert_eq!(rows("C"), 3270);
    assert_eq!(rows("V"), 125);
    assert_eq!(rows("K"), 180);
    assert_eq!(rows("O"), 22);
    assert_eq!(ORACLE.lines().filter(|l| !l.starts_with('#')).count(), 3597);
}

#[test]
fn css_color_rows_match_the_verbatim_baseline() {
    let bad = oracle_mismatches(ORACLE, &PaintRules::BASELINE, "C");
    assert!(
        bad.is_empty(),
        "{} mismatches, first {:?}",
        bad.len(),
        bad.first()
    );
}

#[test]
fn gradient_validity_rows_match_gradgeomok_and_the_two_stop_rule() {
    let bad = oracle_mismatches(ORACLE, &PaintRules::BASELINE, "V");
    assert!(bad.is_empty(), "{:?}", bad.first());
}

#[test]
fn gradient_kind_and_radius_rows_match_the_engine_arithmetic() {
    let bad = oracle_mismatches(ORACLE, &PaintRules::BASELINE, "K");
    assert!(bad.is_empty(), "{:?}", bad.first());
}

#[test]
fn stop_offsets_are_f32_casts_of_the_js_numbers() {
    let bad = oracle_mismatches(ORACLE, &PaintRules::BASELINE, "O");
    assert!(bad.is_empty(), "{:?}", bad.first());
}

#[test]
fn baseline_rules_satisfy_every_pinned_literal() {
    assert_eq!(
        pinned_mismatches(&PaintRules::BASELINE),
        Vec::<String>::new()
    );
}

pub(crate) fn fill(json: &str) -> SolidFill {
    serde_json::from_str(json).expect("solid fill json")
}

#[test]
fn scene_solid_keeps_the_four_original_numbers_unquantized() {
    let source = fill(r#"{"kind":"solid","r":1,"g":0,"b":0.30000000000000004,"a":0.1}"#);
    let solid = SceneSolid::from_fill(&source).expect("in range");
    let [r, g, b, a] = solid.channels();
    assert!(r.is_u64() && g.is_u64(), "integer channels stay integers");
    assert_eq!(*r, source.r);
    assert_eq!(*g, source.g);
    assert_eq!(
        b.as_f64().unwrap().to_bits(),
        0.30000000000000004f64.to_bits()
    );
    assert_eq!(*a, source.a);
    assert_eq!(solid.rgba_f32(), Ok([1.0, 0.0, 0.3f32, 0.1f32]));
    assert_ne!(solid.rgba_f32().unwrap()[2] as f64, 0.30000000000000004f64);
}

#[test]
fn scene_solid_accepts_the_closed_unit_interval_and_negative_zero() {
    let solid = SceneSolid::from_fill(&fill(r#"{"kind":"solid","r":-0.0,"g":1.0,"b":0,"a":1}"#))
        .expect("boundaries are representable");
    let rgba = solid.rgba_f32().unwrap();
    assert!(
        rgba[0] == 0.0 && rgba[0].is_sign_negative(),
        "-0.0 is not normalized"
    );
    assert_eq!(&rgba[1..], &[1.0, 0.0, 1.0]);
}

#[test]
fn scene_solid_rejects_every_out_of_range_channel_like_the_compositor() {
    let bad = [
        "1.0000000000000002",
        "-1",
        "2",
        "-1e-300",
        "1e300",
        "-0.0000001",
    ];
    for value in bad {
        for slot in 0..4 {
            let mut c = ["0.5"; 4];
            c[slot] = value;
            let json = format!(
                r#"{{"kind":"solid","r":{},"g":{},"b":{},"a":{}}}"#,
                c[0], c[1], c[2], c[3]
            );
            assert_eq!(
                SceneSolid::from_fill(&fill(&json)),
                Err(ScenePaintError::UnrepresentableStraightRgba),
                "{json}"
            );
        }
    }
}
